INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT145-S4-Q3$batch13$, 145, 4, 3, $batch13$Paradox$batch13$, $batch13$Researchers have found that the percentage of people who start new businesses is much higher in countries with high per capita income than in countries with moderate per capita income. This is to be expected since most entrepreneurs in high- and middle-income countries start businesses to take advantage of perceived business opportunities, and there are more such opportunities in high-income countries. Surprisingly, however, the researchers also found that the percentage of people who start businesses is even higher in low-income countries than in high-income ones.$batch13$, $batch13$Which one of the following, if true, would most help to explain the researchers’ surprising finding?$batch13$, $batch13$E$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=145 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q3$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$In both high- and low-income countries, well over half of new businesses expect to provide jobs for no more than one or two people.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$Many governments of high-income countries provide assistance to individuals who want to start businesses, but very few governments of low-income countries do so.$batch13$, $batch13$Opposite$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$The percentage of new businesses that fail within a few years of being founded is generally no higher in low-income countries than in high-income countries.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$In high-income countries, many entrepreneurs who start businesses to take advantage of perceived business opportunities soon discover that the opportunities were illusory.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$In low-income countries, most entrepreneurs start businesses because all other employment options are either absent or unsatisfactory.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Fact$batch13$, $batch13$The share of people starting businesses is higher in high-income countries than in middle-income ones, because high-income countries offer more business opportunities.$batch13$), (1, $batch13$Fact$batch13$, $batch13$The share is even higher in low-income countries.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$Low-income countries should have the fewest opportunities, so the opportunity explanation can't cover them. People there must be starting businesses for a different reason.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Give low-income entrepreneurs a different reason to start businesses.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT145-S4-Q3$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Business size is the same in both and doesn't explain the start rates.$batch13$), ($batch13$B$batch13$, $batch13$Government help in high-income countries would raise their rate, which deepens the puzzle.$batch13$), ($batch13$C$batch13$, $batch13$Failure rates don't explain why more people start businesses.$batch13$), ($batch13$D$batch13$, $batch13$Illusory opportunities in high-income countries don't explain the low-income rate.$batch13$), ($batch13$E$batch13$, $batch13$In low-income countries people start businesses out of necessity, because other work is missing or poor. That reason doesn't depend on opportunities.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT145-S4-Q3$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
